/**
 * UUID v7 (RFC 9562): 48-bit Unix ms timestamp + 12-bit monotonic counter + 62 random bits.
 * IDs generated by one process are strictly increasing, even within the same millisecond
 * or when the clock goes backwards, so they double as a creation-order sort key.
 */
let lastMs = -1;
let counter = 0;

export function uuidv7(now: number = Date.now()): string {
  let ms = Math.floor(now);
  if (ms > lastMs) {
    lastMs = ms;
    // Random start leaves headroom for many IDs in the same ms.
    counter = Math.floor(Math.random() * 0x400);
  } else {
    ms = lastMs;
    counter++;
    if (counter > 0xfff) {
      lastMs = ms = lastMs + 1;
      counter = 0;
    }
  }

  const bytes = new Uint8Array(16);
  crypto.getRandomValues(bytes);

  let t = ms;
  for (let i = 5; i >= 0; i--) {
    bytes[i] = t % 256;
    t = Math.floor(t / 256);
  }
  bytes[6] = 0x70 | ((counter >> 8) & 0x0f);
  bytes[7] = counter & 0xff;
  bytes[8] = ((bytes[8] ?? 0) & 0x3f) | 0x80;

  const hex = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
  return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}
